    /// Initializes the SwiftUI wrapper with sample data points and a selected map type
    init(mapType: HMapType = .flatDistinct) {
        self.dataProvider = HeatMapDataProvider(dataPoints: HiOSHeatMap.sampleDataPoints)
        self.mapType = mapType
    }
    
    /// Creates and returns an instance of `HeatMapContainerViewController`
    func makeUIViewController(context: Context) -> HeatMapContainerViewController {
        return HeatMapContainerViewController(dataProvider: dataProvider, mapType: mapType)
    }
    
    /// Updates the `HeatMapContainerViewController` instance when needed
    func updateUIViewController(_ uiViewController: HeatMapContainerViewController, context: Context) {
        // No need for dynamic updates in this implementation
    }
